create policy scorecards_owner_select on public.scorecard_entries for select to authenticated using((select auth.uid())=user_id and (select private.is_org_member(organization_id)));
create policy scorecards_owner_insert on public.scorecard_entries for insert to authenticated with check((select auth.uid())=user_id and (select private.is_org_member(organization_id)));
create policy scorecards_owner_update on public.scorecard_entries for update to authenticated using((select auth.uid())=user_id and (select private.is_org_member(organization_id))) with check((select auth.uid())=user_id and (select private.is_org_member(organization_id)));
create table public.audit_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,event_type text not null,entity_type text not null,entity_id uuid,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
alter table public.audit_events enable row level security;
create policy audit_events_member_insert on public.audit_events for insert to authenticated with check(user_id=(select auth.uid()) and (select private.is_org_member(organization_id)));
